##### 4c. Configuration File — the real Terraform HCL this scenario produces

```hcl
# terraform/main.tf

# Terraform 1.5+ import block — declarative, reviewable in a PR
import {
  to = aws_s3_bucket.audit
  id = "nbi-audit-logs-prod"
}

# The HCL we hand-author to MATCH the live bucket (import does not write this)
resource "aws_s3_bucket" "audit" {
  bucket = var.audit_bucket_name
  tags = {
    team        = "compliance"
    environment = var.environment
  }
}

# We must add these blocks because the live bucket has them.
# Without them, the first plan wrongly proposes to REMOVE them.
resource "aws_s3_bucket_versioning" "audit" {
  bucket = aws_s3_bucket.audit.id
  versioning_configuration {
    status = "Enabled"
  }
}

resource "aws_s3_bucket_server_side_encryption_configuration" "audit" {
  bucket = aws_s3_bucket.audit.id
  rule {
    apply_server_side_encryption_by_default {
      sse_algorithm = "AES256"
    }
  }
}
```

