package com.bank.iac;

import java.util.Map;
import java.util.TreeMap;

// Represents the REAL AWS object that exists before Terraform knows about it.
// The contractor created this manually two years ago.
public class LiveInfrastructure {
    private final String importId;            // AWS uses this as the import ID
    private final Map<String, String> attributes = new TreeMap<>();

    public LiveInfrastructure(String importId) {
        this.importId = importId;
    }

    public void set(String key, String value) {
        attributes.put(key, value);
    }

    public String get(String key) {
        return attributes.get(key);
    }

    public Map<String, String> allAttributes() {
        return new TreeMap<>(attributes);
    }

    public String getImportId() {
        return importId;
    }
}
