package com.bank.iac;

import java.util.HashMap;
import java.util.Map;

// Terraform's record of what it manages. Import writes ONLY here — not into config.
public class TerraformState {
    // address (e.g. "aws_s3_bucket.audit") -> real import ID
    private final Map<String, String> managedAddresses = new HashMap<>();

    public boolean isManaged(String address) {
        return managedAddresses.containsKey(address);
    }

    public void bind(String address, String importId) {
        managedAddresses.put(address, importId);
    }

    public void remove(String address) {
        managedAddresses.remove(address);  // 'terraform state rm' — undoes import, never touches AWS
    }

    public String boundId(String address) {
        return managedAddresses.get(address);
    }
}
