// ─── File: src/main/java/com/bank/iac/ImportEngine.java ───
package com.bank.iac;

import java.util.ArrayList;
import java.util.List;
import java.util.Map;
import java.util.logging.Logger;

// Models the import + plan workflow. Import binds state; plan diffs config vs live.
public class ImportEngine {
    private static final Logger log = Logger.getLogger(ImportEngine.class.getName());

    private final TerraformState state;
    private final LiveInfrastructure live;

    public ImportEngine(TerraformState state, LiveInfrastructure live) {
        this.state = state;
        this.live = live;
    }

    // 'terraform import' — writes to STATE only. Notice it never copies attributes into config.
    public void importResource(String address) {
        state.bind(address, live.getImportId());
        log.info(() -> "IMPORT: bound " + address + " to live ID '" + live.getImportId()
                + "' — state updated, config UNCHANGED");
    }

    // 'terraform plan' — compares the engineer's config against the live resource.
    // Returns the list of proposed changes. Empty list = clean plan = done.
    public List<String> plan(ConfiguredResource config) {
        if (!state.isManaged(config.getAddress())) {
            log.severe(() -> "PLAN: " + config.getAddress()
                    + " not in state — plan would CREATE a duplicate!");
            return List.of("+ create " + config.getAddress() + " (DANGER: duplicate)");
        }
        List<String> changes = new ArrayList<>();
        Map<String, String> desired = config.desiredAttributes();
        Map<String, String> actual = live.allAttributes();

        // Attributes the live resource has but config forgot -> plan wants to REMOVE/CHANGE them
        for (Map.Entry<String, String> e : actual.entrySet()) {
            String want = desired.get(e.getKey());
            if (want == null) {
                changes.add("~ " + e.getKey() + ": will REMOVE live value '" + e.getValue()
                        + "' (config is silent)");
            } else if (!want.equals(e.getValue())) {
                changes.add("~ " + e.getKey() + ": '" + e.getValue() + "' => '" + want + "'");
            }
        }
        if (changes.isEmpty()) {
            log.info(() -> "PLAN: No changes. Config matches live resource. Safe to commit.");
        } else {
            log.warning(() -> "PLAN: " + changes.size()
                    + " unexpected change(s) — config does NOT yet match live. Iterate!");
        }
        return changes;
    }
}
