// ─── File: src/main/java/com/bank/iac/TerraformImportDemo.java ───
package com.bank.iac;

import java.io.IOException;
import java.util.List;
import java.util.logging.*;

// Runnable demo: author -> import -> plan (dirty) -> iterate -> plan (clean) -> commit.
public class TerraformImportDemo {
    private static final Logger log = Logger.getLogger(TerraformImportDemo.class.getName());

    static {
        Logger root = Logger.getLogger("");
        for (Handler h : root.getHandlers()) root.removeHandler(h);
        ConsoleHandler ch = new ConsoleHandler();
        ch.setFormatter(new BankLogFormatter());
        ch.setLevel(Level.ALL);
        root.addHandler(ch);
        root.setLevel(Level.ALL);
    }

    public static void main(String[] args) throws IOException {
        log.info("National Bank of India — adopting legacy audit bucket into Terraform");

        // The real bucket the contractor made manually (versioning + encryption + tag).
        LiveInfrastructure liveBucket = new LiveInfrastructure("nbi-audit-logs-prod");
        liveBucket.set("bucket", "nbi-audit-logs-prod");
        liveBucket.set("versioning", "Enabled");
        liveBucket.set("sse_algorithm", "AES256");
        liveBucket.set("tag_team", "compliance");

        TerraformState state = new TerraformState();
        ImportEngine engine = new ImportEngine(state, liveBucket);

        // Step 1: engineer writes a MINIMAL HCL shell (forgets versioning & encryption).
        ConfiguredResource config = new ConfiguredResource("aws_s3_bucket.audit");
        config.declare("bucket", "nbi-audit-logs-prod");
        config.declare("tag_team", "compliance");

        // Step 2: import binds state ONLY.
        engine.importResource("aws_s3_bucket.audit");

        // Step 3: first plan — DIRTY, because config is missing live settings.
        log.info("First plan after import (expect unexpected changes):");
        List<String> firstPlan = engine.plan(config);
        firstPlan.forEach(c -> log.warning("  " + c));

        // Step 4: iterate — engineer reads the plan and adds the missing blocks to HCL.
        config.declare("versioning", "Enabled");
        config.declare("sse_algorithm", "AES256");

        // Step 5: second plan — CLEAN, now safe to commit the HCL to the repo.
        log.info("Second plan after iterating on config:");
        List<String> secondPlan = engine.plan(config);
        if (secondPlan.isEmpty()) {
            log.info("Clean plan achieved — committing HCL to version control.");
        } else {
            secondPlan.forEach(c -> log.warning("  " + c));
        }
    }
}
